package com.codealpha.flashcards

private data class QuestionDraft(
    val prompt: String,
    val answer: String,
    val explanation: String,
    val distractors: List<String>,
)

private fun draft(prompt: String, answer: String, explanation: String, vararg distractors: String) =
    QuestionDraft(prompt, answer, explanation, distractors.toList())

