        addAll(createQuestions("JavaScript", listOf(
            draft("What does const prevent in JavaScript?", "Reassigning the binding", "const prevents rebinding the variable, but an object or array stored in it can still be mutated.", "Changing any nested object property", "Calling a function", "Reading the variable"),
            draft("What does let provide?", "A block-scoped binding that can be reassigned", "let is block-scoped and its binding may be assigned a new value.", "A global-only constant", "A JSON parser", "An automatically awaited promise"),
            draft("What is a key difference between === and ==?", "=== compares without type coercion", "Strict equality does not coerce values to a common type before comparison.", "=== compares only strings", "== is used only for objects", "They always produce different results"),
            draft("What does Array.prototype.map() return?", "A new array containing each callback result", "map transforms each element and returns an array of the callback's results.", "The first matching element only", "A boolean describing whether all items pass", "The original array sorted in place"),
            draft("What does Array.prototype.filter() return?", "A new array containing items that pass the predicate", "filter keeps elements for which the callback returns a truthy value.", "A single transformed value for every element", "The index of the last element", "A promise for a network request"),
            draft("What does an async function always return?", "A Promise", "An async function wraps its returned value in a promise, or returns a rejected promise if it throws.", "A DOM element", "A CSS rule", "A synchronous generator only"),
            draft("What does await do inside an async function?", "Pauses that function until a promise settles, then produces its result or throws", "await lets asynchronous code be written in a sequential style without blocking the whole JavaScript thread.", "Blocks the browser's entire event loop", "Converts every value into a string", "Starts a new operating-system thread"),
            draft("Where can a rejected promise commonly be handled with async/await?", "Inside a try/catch around the await", "A rejected promise throws at the await expression and can be caught with try/catch.", "Only in a CSS media query", "Only by calling JSON.stringify", "Inside an HTML id attribute"),
            draft("What is a closure?", "A function together with access to its lexical environment", "A closure can use variables from the scope in which the function was created.", "A function that has no parameters", "A closed browser tab", "A method that can only read global variables"),
            draft("How does this in an arrow function behave?", "It is inherited lexically from the surrounding scope", "Arrow functions do not create their own this binding.", "It always refers to the global object", "It is always the function's first argument", "It is chosen by the last object in memory"),
            draft("What does the spread syntax do when used on an array?", "Expands the array's iterable elements in a new expression", "For example, [...items] creates a shallow copy containing the iterable's elements.", "Deep-clones every nested object automatically", "Sorts the array alphabetically", "Converts every item into a promise"),
            draft("What is destructuring used for?", "Extracting values from arrays or properties from objects", "Destructuring assigns parts of an array or object to variables.", "Encrypting a JavaScript file", "Changing a function into a class", "Removing all properties from an object"),
            draft("When does the nullish coalescing operator ?? use its fallback?", "When the left side is null or undefined", "Unlike ||, ?? does not replace valid falsy values such as 0, false, or an empty string.", "Whenever the left side is any falsy value", "Only when the left side is an array", "When the right side is a function"),
            draft("What does optional chaining (?.) help with?", "Safely access a property when an earlier value may be null or undefined", "Optional chaining short-circuits to undefined instead of throwing at that nullish access.", "Call a function repeatedly until it returns true", "Create a new object without properties", "Compare two values strictly"),
            draft("What does JSON.parse() do?", "Converts valid JSON text into a JavaScript value", "JSON.parse reads JSON text and returns its corresponding JavaScript data structure.", "Converts any JavaScript function into JSON safely", "Sends JSON to a server", "Validates HTML tags in a document"),
            draft("What does Array.prototype.find() return?", "The first element that satisfies the predicate, or undefined", "find stops at the first matching element.", "Every matching element in a new array", "The number of matching elements", "A sorted copy of the array"),
            draft("What is event delegation?", "Handle events on a common ancestor for matching descendants", "Delegation uses event bubbling so one ancestor handler can manage many child elements.", "Attach a separate operating-system process to every button", "Move every event into a CSS file", "Prevent all events from bubbling"),
            draft("How do you register a DOM event handler?", "element.addEventListener(eventType, handler)", "addEventListener registers a callback for an event on a target.", "element.onStyle(eventType, handler)", "document.addCSS(eventType, handler)", "element.listenHTML(eventType, handler)"),
            draft("What is debouncing useful for?", "Wait until calls stop briefly before running an action", "Debouncing is useful for actions such as search that should run after a burst of input settles.", "Run an action at a fixed rate while calls continue", "Guarantee that a network request never fails", "Make a synchronous function return a promise"),
            draft("What does setTimeout(callback, delay) do?", "Schedules a callback to run after at least the delay when the event loop can run it", "The delay is a minimum scheduling time, not a guarantee of exact execution time.", "Runs the callback immediately and blocks", "Repeats the callback forever at an exact interval", "Pauses the entire browser for the delay"),
        )))
    }

    private fun createQuestions(topic: String, drafts: List<QuestionDraft>): List<QuizQuestion> =
        drafts.mapIndexed { index, item ->
            val correctOptionIndex = index % OPTION_COUNT
            var distractorIndex = 0
            val options = List(OPTION_COUNT) { optionIndex ->
                if (optionIndex == correctOptionIndex) item.answer else item.distractors[distractorIndex++]
            }
            QuizQuestion(
                id = "${topic.lowercase().replace(' ', '-')}-${index + 1}",
                topic = topic,
                prompt = item.prompt,
                options = options,
                correctOptionIndex = correctOptionIndex,
                explanation = item.explanation,
            )
        }

    private const val OPTION_COUNT = 4
}
